// Einmaliger Nachtrag 2026-07-30: berechnet vorlageDatumPdf/vorlageDatum/verfasser/fachdienst
// fuer alle Zeilen neu, die diese Felder durch den full-row-overwrite-Bug (siehe Fix vom
// 2026-07-30) verloren haben. Identische Extraktionslogik wie P3 "NC Aggregiere Texte" /
// der urspruengliche Backfill vom 2026-07-28, angewandt auf das aktuell gespeicherte
// combinedText (auch wenn das inzwischen im P4-Format vorliegt, enthaelt es denselben
// Dokumentkopf). Gibt NUR Zeilen aus, bei denen tatsaechlich ein neues Datum gefunden wurde,
// als VOLLSTAENDIGE Zeile (alle Spalten), damit der nachfolgende Update-Node keine anderen
// Spalten durch sein defineBelow-Mapping loescht.

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

function extractVorlagenMeta(text) {
  const t = safeStr(text);
  const verfasserMatch = t.match(/([^\n]+)\n\s*Verfasser\/in/);
  const datumMatch = t.match(/Stadt Goslar Goslar,\s*(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  let fachdienst = '';
  if (datumMatch) {
    const rest = t.slice(datumMatch.index + datumMatch[0].length);
    const fdMatch = rest.match(/^\s*\n([^\n]+)\n/);
    if (fdMatch) fachdienst = fdMatch[1].trim();
  }
  const vorlageDatumPdf = datumMatch
    ? `${datumMatch[3]}-${datumMatch[2].padStart(2, '0')}-${datumMatch[1].padStart(2, '0')}`
    : '';
  return { verfasser: verfasserMatch ? verfasserMatch[1].trim() : '', fachdienst, vorlageDatumPdf };
}

const out = [];
for (const item of items) {
  const j = item.json || {};
  if (safeStr(j.vorlageDatum)) continue; // schon gesetzt, nicht anfassen
  if (!safeStr(j.combinedText)) continue; // nichts zu extrahieren
  const meta = extractVorlagenMeta(j.combinedText);
  if (!meta.vorlageDatumPdf) continue; // Muster nicht gefunden
  out.push({
    json: {
      ...j,
      verfasser: meta.verfasser,
      fachdienst: meta.fachdienst,
      vorlageDatumPdf: meta.vorlageDatumPdf,
      vorlageDatum: meta.vorlageDatumPdf
    }
  });
}
return out;
